/* @autogenerated */
import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { Router } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoPipe } from '@jsverse/transloco';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AuthorizationAccessService } from '@shared/context/authorization-access/authorization-access.service';
import { HeroSectionComponent } from '../../sections/hero/hero-section.component';
import { FeaturesSectionComponent } from '../../sections/features/features-section.component';

/**
 * Página de entrada para quien no ha iniciado sesión: ocupa el sitio del shell (sin menú ni cuenta, que sin sesión
 * no ofrecen nada) y explica de qué va la aplicación antes de pedir el login. Los textos salen del i18n
 * (`landing.*` y `sections.features`), así que cada aplicación cuenta lo suyo sin tocar el componente.
 */
@Component({
  selector: 'app-landing',
  standalone: true,
  imports: [MatButtonModule, MatIconModule, TranslocoPipe, HeroSectionComponent, FeaturesSectionComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './landing.component.html',
  styleUrl: './landing.component.scss',
})
export class LandingComponent {
  private readonly identity = inject(IdentityService);
  private readonly access = inject(AuthorizationAccessService);
  private readonly router = inject(Router);

  login(): void {
    // Si un guard mandó aquí desde una ruta protegida (`/unauthorized?returnUrl=...`), tras el login se vuelve a ella
    const returnUrl = this.router.parseUrl(this.router.url).queryParamMap.get('returnUrl');
    if (returnUrl) {
      this.access.remember(returnUrl);
    }
    this.identity.login('main');
  }
}
